{"function": "() => {
  // Look for any buttons or links that might expand content
  const buttons = Array.from(document.querySelectorAll('button, a'));
  const expandButtons = buttons.filter(el => {
    const text = el.textContent.toLowerCase();
    return text.includes('expand') || text.includes('show more') || text.includes('show all') || 
           text.includes('full text') || text.includes('view more') || text.includes('read more');
  });
  return {
    expandButtons: expandButtons.map(b => ({
      text: b.textContent,
      tagName: b.tagName,
      className: b.className,
      id: b.id
    })),
    allButtonsCount: buttons.length
  };
}"}

