{"function": "() => {
  // Look for printer-friendly links
  const links = Array.from(document.querySelectorAll('a'));
  const printerLinks = links.filter(el => {
    const text = el.textContent.toLowerCase();
    const href = el.href.toLowerCase();
    return text.includes('print') || text.includes('printer') || text.includes('full text') || 
           text.includes('complete') || text.includes('all rules') ||
           href.includes('print') || href.includes('printer');
  });
  return {
    printerLinks: printerLinks.map(l => ({
      text: l.textContent,
      href: l.href,
      tagName: l.tagName
    })),
    allLinksCount: links.length
  };
}"}

