{"function": "() => {
  const main = document.querySelector('main');
  if (!main) return 'No main';
  // Remove navigation and sidebar if possible
  const clone = main.cloneNode(true);
  // Remove elements with role navigation or complementary
  const navs = clone.querySelectorAll('[role="navigation"], [role="complementary"], .toolbox, .breadcrumb');
  navs.forEach(n => n.remove());
  // Also remove the right sidebar by class? Might be harder.
  // Let's just get all text nodes in order
  const walker = document.createTreeWalker(clone, NodeFilter.SHOW_TEXT, null, false);
  const lines = [];
  while (walker.nextNode()) {
    const text = walker.currentNode.textContent.trim();
    if (text) lines.push(text);
  }
  return lines.join('\n');
}"}

